import{_ as p,r as n,o,c as l,e as s,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const A=JSON.parse('{"title":"介绍 - October CMS - 3.x","titleTemplate":false,"description":"October CMS 附带了一个简单而精简的 AJAX 框架。","frontmatter":{"subtitle":"October CMS 附带了一个简单而精简的 AJAX 框架。"},"headers":[{"level":2,"title":"引入框架","slug":"引入框架","link":"#引入框架","children":[{"level":3,"title":"额外功能","slug":"额外功能","link":"#额外功能","children":[]}]},{"level":2,"title":"AJAX 请求的工作原理","slug":"ajax-请求的工作原理","link":"#ajax-请求的工作原理","children":[]},{"level":2,"title":"使用示例","slug":"使用示例","link":"#使用示例","children":[{"level":4,"title":"另请参阅","slug":"另请参阅","link":"#另请参阅","children":[]}]}],"relativePath":"3.x/zh-cn/cms/ajax/introduction.md","filePath":"3.x/zh-cn/cms/ajax/introduction.md"}'),u={name:"3.x/zh-cn/cms/ajax/introduction.md"};function r(k,a,g,d,m,h){const t=n("pre-heading"),e=n("post-heading");return o(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"介绍",-1)),s(e),a[1]||(a[1]=i(`<p>October CMS 包含一个 AJAX 框架，提供了一整套功能，允许您在不刷新浏览器的情况下从服务器加载数据。同样的库可以在 CMS 主题和管理面板的任何地方使用。</p><p>AJAX 框架有两种使用方式，您可以使用 <a href="./javascript-api.html">JavaScript API</a> 或<a href="./attributes-api.html">数据属性 API</a>。数据属性 API 不需要任何 JavaScript 知识即可在 October CMS 中使用 AJAX。</p><h2 id="引入框架"><a href="#引入框架" class="header-anchor">#</a> 引入框架</h2><div class="custom-block aside"><p>AJAX 框架在您的 CMS 主题中是可选的，您始终可以引入您偏好的框架来替代它。</p></div><p>在处理您的 <a href="./../../cms/themes/themes.html">CMS 主题</a>时，使用该库就像用 Twig 标签引入它一样简单。将 <code>{% framework %}</code> 标签放置在页面或布局中的任意位置。这将添加一个对 October CMS 前端 JavaScript 库的引用，例如：</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h3 id="额外功能"><a href="#额外功能" class="header-anchor">#</a> 额外功能</h3><p><code>{% framework %}</code> 标签支持一个可选的 <strong>extras</strong> 参数，该参数包含额外的样式表和 JavaScript 文件，用于实现额外功能，包括<a href="./../features/validation.html">表单验证</a>、<a href="./../features/loaders.html">加载指示器</a>和<a href="./../features/flash-messages.html">闪存消息</a>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>您还可以添加 <strong>turbo</strong> 参数以在每个页面上启用 <a href="./turbo-router.html">Turbo 路由</a>。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">framework</span> extras turbo <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="ajax-请求的工作原理"><a href="#ajax-请求的工作原理" class="header-anchor">#</a> AJAX 请求的工作原理</h2><p>页面可以通过数据属性或使用 JavaScript 发起 AJAX 请求。每个请求都会调用服务器上的<strong>事件处理程序</strong>（也称为 <a href="./handlers.html">AJAX 处理程序</a>），并且可以使用部件更新页面元素。AJAX 请求与表单配合使用效果最佳，因为表单数据会自动发送到服务器。以下是请求的工作流程：</p><ol><li>客户端浏览器通过提供处理程序名称和其他可选参数发起 AJAX 请求。</li><li>服务器找到 <a href="./handlers.html">AJAX 处理程序</a>并执行它。</li><li>处理程序执行所需的业务逻辑，并通过注入页面变量来更新环境。</li><li>服务器通过 <code>update</code> 选项<a href="./update-partials.html">渲染客户端请求的部件</a>。</li><li>服务器发送包含已渲染部件标记的响应。</li><li>客户端框架使用从服务器接收到的部件数据更新页面元素。</li></ol><h2 id="使用示例"><a href="#使用示例" class="header-anchor">#</a> 使用示例</h2><p>下面是一个简单的示例，使用数据属性 API 定义一个启用 AJAX 的表单。该表单将向 <strong>onTest</strong> 处理程序发起 AJAX 请求，并请求使用 <strong>mypartial</strong> 部件的标记更新结果容器。</p><div class="custom-block tip"><p><code>value1</code> 和 <code>value2</code> 的表单数据会随 AJAX 请求自动发送。</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token comment">&lt;!-- AJAX enabled form --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>form</span> <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onTest<span class="token punctuation">&quot;</span></span> <span class="token attr-name">data-request-update</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>{ mypartial: &#39;#myDiv&#39; }<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Input two values --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value1<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span> + <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>input</span> <span class="token attr-name">name</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>value2<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>

    <span class="token comment">&lt;!-- Action button --&gt;</span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span> <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>submit<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Calculate<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>

<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>form</span><span class="token punctuation">&gt;</span></span>

<span class="token comment">&lt;!-- Result container --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">id</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>myDiv<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div></div><p><strong>mypartial</strong> 部件包含读取 <code>result</code> 变量的标记。</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>p</span><span class="token punctuation">&gt;</span></span>The answer is <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> result <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>p</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p><strong>onTest</strong> 处理程序方法使用 <code>input</code> <a href="./../../extend/services/helpers.html">辅助方法</a>访问表单数据，并将结果传递给 <code>result</code> 页面变量。</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onTest</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token variable">$this</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;result&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value1&#39;</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token function">input</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;value2&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><p>该示例可以这样理解：&quot;当表单提交时，向 <strong>onTest</strong> 处理程序发起 AJAX 请求。当处理程序完成后，渲染 <strong>mypartial</strong> 部件并将其内容注入到 <strong>#myDiv</strong> 元素中。&quot;</p><h4 id="另请参阅"><a href="#另请参阅" class="header-anchor">#</a> 另请参阅</h4><div class="custom-block also"><ul><li><a href="./javascript-api.html">JavaScript API</a></li><li><a href="./attributes-api.html">数据属性 API</a></li></ul></div>`,24))])}const f=p(u,[["render",r]]);export{A as __pageData,f as default};
